  if (!CHAPTER_LEVEL_ID.test(id)) {
    throw new ConfigLoadError(configPath, '仅允许章节内 L01 至 L12');
  }
  return id;
}

function assertTargetId(value: unknown, configPath: string, pattern: RegExp): string {
  return assertId(value, configPath, pattern);
